(root / "bulletengine" / "bulletengine.py").write_bytes(b'"""\nbulletengine.py \xe2\x80\x94 High-performance bullet-hell engine (Structure of Arrays).\n\nManages up to `max_bullets` simultaneous projectiles using flat arrays for\ncache-friendly iteration.  Supports:\n\n  - Multiple bullet types with custom sprites / procedural shapes\n  - Per-bullet image rendering with optional velocity-rotation\n  - Homing / tracking behaviour\n  - Attack-type plug-in system (see attack_types/)\n\n--------------------------------------------------------------------\nQUICK START\n--------------------------------------------------------------------\n\n    import pygame\n    from bulletengine.bulletengine import BulletHellEngine\n\n    engine = BulletHellEngine(max_bullets=60000)\n\n    # Spawn a single bullet\n    engine.spawn_at_angle(x=400, y=300, angle=45, speed=200)\n\n    # Spawn a laser bullet\n    engine.spawn_at_angle(400, 300, 90, 300, bullet_type="laser")\n\n    # Game loop\n    engine.update(dt, px, py, pr, left=0, right=800, top=0, bottom=600)\n    engine.draw(screen)\n\n--------------------------------------------------------------------\n"""\n\nimport math\n\n\nclass BulletHellEngine:\n    """\n    High-performance bullet manager using Structure of Arrays (SoA) design.\n\n    Every property is stored as a flat Python list so that the update loop\n    iterates contiguous memory rather than chasing object pointers.\n\n    Attributes:\n        max (int):          Hard cap on simultaneous bullets.\n        active_count (int): Current number of live bullets.\n        active_attacks:     List of registered AttackType instances.\n    """\n\n    def __init__(self, max_bullets: int = 60000):\n        """\n        Args:\n            max_bullets: Maximum simultaneous bullets.  Tune down on weak\n                         hardware; tune up for dense patterns.  Default 60 000.\n        """\n        self.max = max_bullets\n\n        # -- Kinematics --\n        self.x   = [0.0] * self.max\n        self.y   = [0.0] * self.max\n        self.vx  = [0.0] * self.max\n        self.vy  = [0.0] * self.max\n        \n        # -- Rotation --\n        self.angle            = [0.0]  * self.max   # Rotation angle in degrees\n        self.angular_velocity = [0.0]  * self.max   # Rotation speed in degrees/second\n\n        # -- Shape & lifetime --\n        self.size         = [2]            * self.max\n        self.lifetime     = [0.0]          * self.max   # Current age (seconds)\n        self.max_lifetime = [float(\'inf\')] * self.max   # 0 / inf = unlimited\n        self.active       = [False]        * self.max\n\n        # -- Visuals --\n        self.color       = [(255, 70, 70)] * self.max   # Fallback RGB\n        self.bullet_type = ["dot"]         * self.max   # Type key (str)\n\n        # -- Collision --\n        self.hit_player  = [False] * self.max\n        self.hit_half_w  = [0.0]  * self.max   # OBB half-width  (0 = use circle)\n        self.hit_half_h  = [0.0]  * self.max   # OBB half-height (0 = use circle)\n\n        # -- Homing --\n        self.target_x        = [0.0] * self.max\n        self.target_y        = [0.0] * self.max\n        self.homing_strength = [0.0] * self.max   # 0 = straight, 1 = instant\n\n        # -- Object pool --\n        self.free_list  = list(range(self.max))\n        self.free_count = self.max\n        self.active_count = 0\n\n        # -- Attack types --\n        self.active_attacks = []\n\n        # -- Surface cache: {(type_key, size) -> pygame.Surface} --\n        self._surf_cache: dict = {}\n\n    # ---------------------------------------------------------------\n    # Spawning\n    # ---------------------------------------------------------------\n\n    def spawn(\n        self,\n        x: float,\n        y: float,\n        vx: float,\n        vy: float,\n        *,\n        size:        int   = 2,\n        lifetime:    float = float(\'inf\'),\n        color:       tuple = (255, 70, 70),\n        bullet_type: str   = "dot",\n        angular_velocity: float = 0.0,\n    ):\n        """\n        Spawn a bullet using explicit velocity components.\n\n        Args:\n            x, y:        World position (pixels).\n            vx, vy:      Velocity components (pixels / second).\n            size:        Collision radius (pixels).\n            lifetime:    Max age before auto-despawn (seconds).\n                         Use ``float(\'inf\')`` for no expiry.\n            color:       RGB tuple override.  If None, uses the type default.\n            bullet_type: String key from BulletTypes (e.g. ``"laser"``).\n            angular_velocity: Rotation speed in degrees/second.\n\n        Returns:\n            int | None: Bullet index, or None if the pool is exhausted.\n        """\n        if self.free_count <= 0:\n            return None\n\n        idx = self.free_list[self.free_count - 1]\n        self.free_count -= 1\n\n        self.x[idx]            = x\n        self.y[idx]            = y\n        self.vx[idx]           = vx\n        self.vy[idx]           = vy\n        self.size[idx]         = size\n        self.lifetime[idx]     = 0.0\n        self.max_lifetime[idx] = lifetime\n        self.active[idx]       = True\n        self.color[idx]        = color\n        self.bullet_type[idx]  = bullet_type\n        self.hit_player[idx]   = False\n        self.hit_half_w[idx]   = 0.0\n        self.hit_half_h[idx]   = 0.0\n        self.homing_strength[idx] = 0.0\n        self.angle[idx]           = 0.0\n        self.angular_velocity[idx] = angular_velocity\n\n        self.active_count += 1\n        return idx\n\n    def spawn_at_angle(\n        self,\n        x: float,\n        y: float,\n        angle: float,\n        speed: float,\n        *,\n        size:        int   = 2,\n        lifetime:    float = float(\'inf\'),\n        color:       tuple = (255, 70, 70),\n        bullet_type: str   = "dot",\n        angular_velocity: float = 0.0,\n    ):\n        """\n        Spawn a bullet using angle + speed instead of raw velocity.\n\n        Args:\n            x, y:        World position.\n            angle:       Direction in degrees (0 = right, 90 = down).\n            speed:       Magnitude in pixels / second.\n            size:        Collision radius.\n            lifetime:    Auto-despawn age (seconds).\n            color:       RGB override.\n            bullet_type: String key from BulletTypes.\n            angular_velocity: Rotation speed in degrees/second.\n\n        Returns:\n            int | None: Bullet index, or None if pool exhausted.\n\n        Example::\n\n            # Fire a laser upward\n            engine.spawn_at_angle(400, 300, 270, 400, bullet_type="laser")\n        """\n        rad = math.radians(angle)\n        return self.spawn(\n            x, y,\n            math.cos(rad) * speed,\n            math.sin(rad) * speed,\n            size=size,\n            lifetime=lifetime,\n            color=color,\n            bullet_type=bullet_type,\n            angular_velocity=angular_velocity,\n        )\n\n    def spawn_homing(\n        self,\n        x: float,\n        y: float,\n        vx: float,\n        vy: float,\n        target_x: float,\n        target_y: float,\n        *,\n        homing_strength: float = 0.5,\n        size:            int   = 2,\n        lifetime:        float = float(\'inf\'),\n        color:           tuple = (255, 70, 70),\n        bullet_type:     str   = "dot",\n    ):\n        """\n        Spawn a bullet that curves toward a target.\n\n        The bullet starts with velocity ``(vx, vy)`` and each frame nudges\n        toward ``(target_x, target_y)`` proportionally to ``homing_strength``.\n        Call ``engine.target_x[idx] = new_x`` every frame to update the target.\n\n        Args:\n            x, y:             Spawn position.\n            vx, vy:           Initial velocity (pixels / second).\n            target_x, target_y: Position to track.\n            homing_strength:  Tracking aggressiveness.\n                              ``0.0`` \xe2\x86\x92 straight line.\n                              ``0.5`` \xe2\x86\x92 moderate curve.\n                              ``1.0`` \xe2\x86\x92 instant direction flip.\n            size:             Collision radius.\n            lifetime:         Auto-despawn age.\n            color:            RGB override.\n            bullet_type:      String key from BulletTypes.\n\n        Returns:\n            int | None: Bullet index, or None if pool exhausted.\n        """\n        idx = self.spawn(\n            x, y, vx, vy,\n            size=size, lifetime=lifetime, color=color, bullet_type=bullet_type,\n        )\n        if idx is not None:\n            self.target_x[idx]        = target_x\n            self.target_y[idx]        = target_y\n            self.homing_strength[idx] = max(0.0, min(1.0, homing_strength))\n        return idx\n\n    # ---------------------------------------------------------------\n    # Update\n    # ---------------------------------------------------------------\n\n    def update(\n        self,\n        dt: float,\n        px: float,\n        py: float,\n        pr: float,\n        left:   float,\n        right:  float,\n        top:    float,\n        bottom: float,\n        on_hit=None,\n    ):\n        """\n        Advance physics, lifetime, and collision for all active bullets.\n\n        Args:\n            dt:                 Delta time in seconds.\n            px, py:             Player centre position.\n            pr:                 Player collision radius.\n            left, right:        Horizontal arena bounds.\n            top, bottom:        Vertical arena bounds.\n            on_hit:             Optional callback ``fn(bullet_index)`` called\n                                when a bullet hits the player.\n\n        Notes:\n            Bullets are culled 500 px outside the arena bounds, so patterns\n            that spawn just off-screen have time to enter the play area.\n        """\n        i = 0\n        while i < self.max:\n            if not self.active[i]:\n                i += 1\n                continue\n\n            # --- Homing ---\n            if self.homing_strength[i] > 0:\n                dx   = self.target_x[i] - self.x[i]\n                dy   = self.target_y[i] - self.y[i]\n                dist = math.sqrt(dx * dx + dy * dy)\n                if dist > 0:\n                    spd     = math.sqrt(self.vx[i] ** 2 + self.vy[i] ** 2) or 1.0\n                    want_vx = (dx / dist) * spd\n                    want_vy = (dy / dist) * spd\n                    s = self.homing_strength[i]\n                    self.vx[i] += (want_vx - self.vx[i]) * s\n                    self.vy[i] += (want_vy - self.vy[i]) * s\n\n            # --- Movement ---\n            self.x[i] += self.vx[i] * dt\n            self.y[i] += self.vy[i] * dt\n            \n            # --- Rotation ---\n            self.angle[i] += self.angular_velocity[i] * dt\n\n            # --- Lifetime ---\n            ml = self.max_lifetime[i]\n            if ml != float(\'inf\') and ml > 0:\n                self.lifetime[i] += dt\n                if self.lifetime[i] >= ml:\n                    self._deactivate(i)\n                    i += 1\n                    continue\n\n            # --- Bounds cull ---\n            if (self.x[i] < left  - 500 or self.x[i] > right  + 500 or\n                self.y[i] < top   - 500 or self.y[i] > bottom + 500):\n                self._deactivate(i)\n                i += 1\n                continue\n\n            # --- Player collision (OBB vs circle when rotated, else circle-circle) ---\n            if not self.hit_player[i]:\n                dx = self.x[i] - px\n                dy = self.y[i] - py\n                hw = self.hit_half_w[i]\n                hh = self.hit_half_h[i]\n                if hw > 0 and hh > 0:\n                    # Rotate player position into bullet local space\n                    ang = math.radians(-self.angle[i])\n                    cos_a = math.cos(ang)\n                    sin_a = math.sin(ang)\n                    lx = cos_a * dx - sin_a * dy\n                    ly = sin_a * dx + cos_a * dy\n                    # Clamp to OBB edge, measure remaining distance to circle\n                    cx2 = max(-hw, min(hw, lx))\n                    cy2 = max(-hh, min(hh, ly))\n                    dist_sq = (lx - cx2) ** 2 + (ly - cy2) ** 2\n                    hit = dist_sq < pr * pr\n                else:\n                    dist_sq = dx * dx + dy * dy\n                    hit = dist_sq < (self.size[i] + pr) ** 2\n                if hit:\n                    self.hit_player[i] = True\n                    if on_hit:\n                        on_hit(i)\n                    self._deactivate(i)\n                    i += 1\n                    continue\n\n            i += 1\n\n    # ---------------------------------------------------------------\n    # Draw\n    # ---------------------------------------------------------------\n\n    def draw(self, screen):\n        """\n        Render all active bullets to a pygame surface.\n\n        Bullets with a sprite (image_path set on their BulletType) are drawn\n        via ``blit``; procedural shapes use ``pygame.draw``.  Rotation is\n        applied for types with ``rotate_to_velocity=True``.\n\n        Args:\n            screen: A ``pygame.Surface`` to draw onto.\n        """\n        import pygame\n        from .bullet_types import BulletTypes\n\n        for i in range(self.max):\n            if not self.active[i]:\n                continue\n\n            btype = BulletTypes.get(self.bullet_type[i])\n            sz    = self.size[i]\n            cx    = int(self.x[i])\n            cy    = int(self.y[i])\n\n            # --- Try to get/make a surface ---\n            cache_key = (self.bullet_type[i], sz)\n            surf = self._surf_cache.get(cache_key)\n\n            if surf is None:\n                surf = btype.make_surface(sz)\n                self._surf_cache[cache_key] = surf  # may be None\n\n            if surf is not None:\n                # Determine rotation angle\n                angle_deg = self.angle[i]  # Use stored angle\n                \n                # If rotate_to_velocity is enabled and velocity exists AND angular velocity is not being used, use velocity direction\n                if btype.rotate_to_velocity and self.angular_velocity[i] == 0.0 and (self.vx[i] != 0 or self.vy[i] != 0):\n                    angle_deg = math.degrees(math.atan2(self.vy[i], self.vx[i]))\n                \n                # Apply rotation\n                draw_surf = pygame.transform.rotate(surf, -angle_deg)\n                # Sync OBB to pre-rotation surface dimensions\n                sw, sh = surf.get_size()\n                self.hit_half_w[i] = sw / 2\n                self.hit_half_h[i] = sh / 2\n\n                rect = draw_surf.get_rect(center=(cx, cy))\n                screen.blit(draw_surf, rect)\n            else:\n                # Fallback: plain circle\n                pygame.draw.circle(screen, self.color[i], (cx, cy), max(1, sz))\n\n    # ---------------------------------------------------------------\n    # Pool management\n    # ---------------------------------------------------------------\n\n    def _deactivate(self, idx: int):\n        """Return bullet at *idx* to the free pool (O(1))."""\n        self.active[idx] = False\n        self.free_list[self.free_count] = idx\n        self.free_count  += 1\n        self.active_count -= 1\n\n    def clear(self):\n        """Despawn all active bullets immediately."""\n        for i in range(self.max):\n            if self.active[i]:\n                self._deactivate(i)\n\n    # ---------------------------------------------------------------\n    # Attack type system\n    # ---------------------------------------------------------------\n\n    def add_attack(self, attack_type):\n        """\n        Register an AttackType instance so it is updated automatically.\n\n        Args:\n            attack_type: Any subclass of BaseAttackType.\n        """\n        self.active_attacks.append(attack_type)\n\n    def remove_attack(self, attack_type):\n        """\n        Unregister an AttackType instance.\n\n        Args:\n            attack_type: Previously added AttackType instance.\n        """\n        if attack_type in self.active_attacks:\n            self.active_attacks.remove(attack_type)\n\n    def update_attacks(self, dt: float, *args, **kwargs):\n        """\n        Call ``update(dt, engine, *args, **kwargs)`` on every registered attack.\n\n        Args:\n            dt:       Delta time in seconds.\n            *args:    Forwarded to each attack\'s update() \xe2\x80\x94 typically\n                      ``player_x, player_y``.\n            **kwargs: Extra keyword arguments forwarded to each attack.\n\n        Example::\n\n            engine.update_attacks(dt, player_x, player_y)\n        """\n        for attack in self.active_attacks:\n            attack.update(dt, self, *args, **kwargs)\n\n    # ---------------------------------------------------------------\n    # Utilities\n    # ---------------------------------------------------------------\n\n    def get_stats(self) -> dict:\n        """\n        Return a snapshot of engine state for debugging / HUD display.\n\n        Returns:\n            dict with keys:\n                ``active_bullets``   \xe2\x80\x94 currently live bullet count\n                ``max_bullets``      \xe2\x80\x94 pool capacity\n                ``pool_usage``       \xe2\x80\x94 usage percentage (0\xe2\x80\x93100)\n                ``free_slots``       \xe2\x80\x94 available pool slots\n                ``active_attacks``   \xe2\x80\x94 number of registered attack types\n        """\n        return {\n            \'active_bullets\': self.active_count,\n            \'max_bullets\':    self.max,\n            \'pool_usage\':     self.active_count / self.max * 100,\n            \'free_slots\':     self.free_count,\n            \'active_attacks\': len(self.active_attacks),\n        }\n\n    def invalidate_surface_cache(self):\n        """\n        Clear cached bullet surfaces.\n\n        Call this if you change a BulletType\'s properties at runtime and want\n        the new visuals to take effect immediately.\n        """\n        self._surf_cache.clear()\n\n    def register_btype(self, name_for_btype, img_path=None, size=4, rotate_to_vel=False, glow=False):\n        """\n        Register a new bullet_type\n\n        Use this if the type of bullet isnt there\n        """\n        from .bullet_types import BulletTypes\n        return BulletTypes.register(name_for_btype, image_path=img_path, size=size, rotate_to_velocity=rotate_to_vel, glow=glow)')
(root / "bulletengine" / "bullet_types.py").write_bytes(b'"""\nbullet_types.py \xe2\x80\x94 Bullet type definitions & registry.\n\nA BulletType describes how a bullet looks and behaves visually.\nPass a BulletType (or its string key) to spawn() / spawn_at_angle() /\nspawn_homing() to get different visuals and default properties.\n\n--------------------------------------------------------------------\nQUICK USAGE\n--------------------------------------------------------------------\n\n    from bulletengine.bullet_types import BulletTypes\n\n    # Use a built-in type by name\n    engine.spawn_at_angle(x, y, angle, speed, bullet_type="laser")\n\n    # Use the constant directly (autocomplete-friendly)\n    engine.spawn_at_angle(x, y, angle, speed, bullet_type=BulletTypes.ORB)\n\n    # Register a custom type with a sprite image\n    BulletTypes.register(\n        "my_bullet",\n        image_path="sprites/my_bullet.png",\n        size=6,\n        color=(255, 200, 0),\n        rotate_to_velocity=True,\n    )\n\n--------------------------------------------------------------------\nBUILT-IN TYPES\n--------------------------------------------------------------------\n\n    "dot"       \xe2\x80\x94 tiny coloured dot (default, fastest to draw)\n    "orb"       \xe2\x80\x94 glowing soft circle with alpha\n    "laser"     \xe2\x80\x94 thin elongated needle\n    "needle"    \xe2\x80\x94 sharp pointed shard\n    "star"      \xe2\x80\x94 4-point star shape\n    "ring"      \xe2\x80\x94 hollow ring / donut\n    "crystal"   \xe2\x80\x94 angular diamond shape\n    "fire"      \xe2\x80\x94 animated orange teardrop\n    "ice"       \xe2\x80\x94 pale blue shard\n    "plasma"    \xe2\x80\x94 bright neon core + outer glow\n    "image"     \xe2\x80\x94 use a custom sprite (set image_path)\n\n--------------------------------------------------------------------\n"""\n\nimport math\nimport os\nfrom dataclasses import dataclass, field\nfrom typing import Optional, Tuple\n\ntry:\n    import pygame\n    _PYGAME_AVAILABLE = True\nexcept ImportError:\n    _PYGAME_AVAILABLE = False\n\n\n@dataclass\nclass BulletType:\n    """\n    Describes the visual properties of a bullet type.\n\n    Attributes:\n        key:               Unique string identifier (e.g. "laser").\n        color:             Default RGB color tuple used when no override given.\n        size:              Default collision radius (pixels).\n        image_path:        Optional path to a sprite image file.\n        rotate_to_velocity: If True the sprite is rotated to match movement dir.\n        glow:              Draw a soft glow behind the bullet (pygame only).\n        glow_radius:       Radius of the glow effect in pixels.\n        glow_alpha:        Alpha of the glow (0-255).\n        shape:             Internal draw-mode used when no image is loaded.\n                           One of: "circle", "needle", "star", "ring",\n                                   "crystal", "teardrop", "diamond"\n        scale:             Multiplier applied on top of per-bullet size.\n    """\n    key:                str\n    color:              Tuple[int, int, int] = (255, 70, 70)\n    size:               int                 = 4\n    image_path:         Optional[str]       = None\n    rotate_to_velocity: bool                = False\n    glow:               bool                = False\n    glow_radius:        int                 = 8\n    glow_alpha:         int                 = 80\n    shape:              str                 = "circle"   # fallback draw mode\n    scale:              float               = 1.0\n\n    # --- internal cache, not part of public API ---\n    _surface:           Optional[object]    = field(default=None, init=False, repr=False, compare=False)\n    _surface_loaded:    bool                = field(default=False, init=False, repr=False, compare=False)\n\n    def get_surface(self, size_override: int = 0) -> Optional[object]:\n        """\n        Return a cached pygame.Surface for this type, loading/scaling on demand.\n        Returns None if pygame is not available or no image is set.\n\n        Args:\n            size_override: If > 0, scale the image to this pixel diameter.\n        """\n        if not _PYGAME_AVAILABLE:\n            return None\n        if not self.image_path:\n            return None\n\n        diameter = max(1, (size_override or self.size) * 2)\n\n        # Load raw image once, scale to requested diameter each call\n        if not self._surface_loaded:\n            try:\n                self._surface = pygame.image.load(self.image_path).convert_alpha()\n            except Exception as e:\n                print(f"[BulletTypes] Could not load \'{self.image_path}\': {e}")\n                self._surface = None\n            self._surface_loaded = True\n\n        if self._surface is None:\n            return None\n        # Scale to diameter while keeping aspect ratio\n        raw_w, raw_h = self._surface.get_size()\n        if raw_w == 0 or raw_h == 0:\n            return None\n        if raw_w >= raw_h:\n            new_w = diameter\n            new_h = max(1, int(diameter * raw_h / raw_w))\n        else:\n            new_h = diameter\n            new_w = max(1, int(diameter * raw_w / raw_h))\n        return pygame.transform.smoothscale(self._surface, (new_w, new_h))\n\n    def make_surface(self, size: int) -> Optional[object]:\n        """\n        Create (or retrieve cached) a pygame.Surface for this bullet at the\n        given radius. Handles both image-based and procedural shapes.\n\n        Args:\n            size: Bullet collision radius in pixels.\n        """\n        if not _PYGAME_AVAILABLE:\n            return None\n\n        diameter = max(2, int(size * 2 * self.scale))\n\n        if self.image_path:\n            return self.get_surface(size)\n\n        # -- procedural shapes --\n        surf = pygame.Surface((diameter, diameter), pygame.SRCALPHA)\n        cx = cy = diameter // 2\n        r = max(1, diameter // 2)\n        c = self.color\n\n        if self.shape == "circle":\n            pygame.draw.circle(surf, (*c, 220), (cx, cy), r)\n\n        elif self.shape == "ring":\n            pygame.draw.circle(surf, (*c, 220), (cx, cy), r, max(1, r // 3))\n\n        elif self.shape == "needle":\n            # Thin horizontal line (rotated at draw-time if rotate_to_velocity)\n            hw = max(2, diameter)\n            hh = max(1, diameter // 5)\n            rect = pygame.Rect(0, cy - hh // 2, hw, hh)\n            pygame.draw.ellipse(surf, (*c, 230), rect)\n\n        elif self.shape == "star":\n            _draw_star(surf, cx, cy, r, 4, c)\n\n        elif self.shape == "crystal":\n            _draw_crystal(surf, cx, cy, r, c)\n\n        elif self.shape == "teardrop":\n            _draw_teardrop(surf, cx, cy, r, c)\n\n        elif self.shape == "diamond":\n            _draw_diamond(surf, cx, cy, r, c)\n\n        else:\n            pygame.draw.circle(surf, (*c, 220), (cx, cy), r)\n\n        if self.glow:\n            gsurf = pygame.Surface((diameter + self.glow_radius * 2,\n                                    diameter + self.glow_radius * 2), pygame.SRCALPHA)\n            gr = r + self.glow_radius\n            gcx = gcy = gr\n            pygame.draw.circle(gsurf, (*c, self.glow_alpha), (gcx, gcy), gr)\n            combined = pygame.Surface(gsurf.get_size(), pygame.SRCALPHA)\n            combined.blit(gsurf, (0, 0))\n            combined.blit(surf, (self.glow_radius, self.glow_radius))\n            return combined\n\n        return surf\n\n\n# ---------------------------------------------------------------------------\n# Helper draw functions\n# ---------------------------------------------------------------------------\n\ndef _draw_star(surf, cx, cy, r, points, color):\n    """Draw a N-pointed star."""\n    verts = []\n    inner = r * 0.45\n    for i in range(points * 2):\n        angle = math.radians(i * 180 / points - 90)\n        radius = r if i % 2 == 0 else inner\n        verts.append((cx + math.cos(angle) * radius,\n                       cy + math.sin(angle) * radius))\n    if len(verts) >= 3:\n        pygame.draw.polygon(surf, (*color, 230), verts)\n\n\ndef _draw_crystal(surf, cx, cy, r, color):\n    """Draw a hexagonal crystal."""\n    verts = []\n    for i in range(6):\n        angle = math.radians(i * 60 - 90)\n        verts.append((cx + math.cos(angle) * r,\n                       cy + math.sin(angle) * r))\n    if len(verts) >= 3:\n        pygame.draw.polygon(surf, (*color, 220), verts)\n        pygame.draw.polygon(surf, (255, 255, 255, 80), verts, max(1, r // 6))\n\n\ndef _draw_teardrop(surf, cx, cy, r, color):\n    """Draw a teardrop / flame shape (wider at bottom)."""\n    pygame.draw.circle(surf, (*color, 230), (cx, cy + r // 3), max(1, r * 2 // 3))\n    tip = [(cx, cy - r), (cx - r // 2, cy + r // 3), (cx + r // 2, cy + r // 3)]\n    if len(tip) >= 3:\n        pygame.draw.polygon(surf, (*color, 230), tip)\n\n\ndef _draw_diamond(surf, cx, cy, r, color):\n    """Draw a 4-point diamond."""\n    verts = [\n        (cx,          cy - r),\n        (cx + r // 2, cy),\n        (cx,          cy + r),\n        (cx - r // 2, cy),\n    ]\n    pygame.draw.polygon(surf, (*color, 230), verts)\n    pygame.draw.polygon(surf, (255, 255, 255, 60), verts, max(1, r // 5))\n\n\n# ---------------------------------------------------------------------------\n# Built-in type definitions\n# ---------------------------------------------------------------------------\n\n_BUILTINS: list[BulletType] = [\n    BulletType(\n        key="dot",\n        color=(255, 70, 70),\n        size=2,\n        shape="circle",\n        glow=False,\n    ),\n    BulletType(\n        key="orb",\n        color=(255, 120, 120),\n        size=5,\n        shape="circle",\n        glow=True,\n        glow_radius=6,\n        glow_alpha=70,\n    ),\n    BulletType(\n        key="laser",\n        color=(255, 255, 100),\n        size=2,\n        shape="needle",\n        rotate_to_velocity=True,\n        scale=2.5,\n    ),\n    BulletType(\n        key="needle",\n        color=(200, 255, 200),\n        size=3,\n        shape="needle",\n        rotate_to_velocity=True,\n        scale=1.6,\n    ),\n    BulletType(\n        key="star",\n        color=(255, 220, 50),\n        size=5,\n        shape="star",\n        glow=True,\n        glow_radius=4,\n        glow_alpha=60,\n    ),\n    BulletType(\n        key="ring",\n        color=(100, 200, 255),\n        size=5,\n        shape="ring",\n    ),\n    BulletType(\n        key="crystal",\n        color=(150, 100, 255),\n        size=5,\n        shape="crystal",\n        glow=True,\n        glow_radius=5,\n        glow_alpha=55,\n    ),\n    BulletType(\n        key="fire",\n        color=(255, 140, 30),\n        size=5,\n        shape="teardrop",\n        rotate_to_velocity=True,\n        glow=True,\n        glow_radius=6,\n        glow_alpha=65,\n    ),\n    BulletType(\n        key="ice",\n        color=(180, 230, 255),\n        size=4,\n        shape="crystal",\n        glow=True,\n        glow_radius=4,\n        glow_alpha=50,\n    ),\n    BulletType(\n        key="plasma",\n        color=(200, 50, 255),\n        size=4,\n        shape="circle",\n        glow=True,\n        glow_radius=10,\n        glow_alpha=90,\n    ),\n    BulletType(\n        key="image",\n        color=(255, 255, 255),\n        size=4,\n        image_path=None,   # set via register() or directly\n        rotate_to_velocity=False,\n    ),\n]\n\n\nclass _BulletTypeRegistry:\n    """\n    Singleton registry mapping string keys \xe2\x86\x92 BulletType objects.\n\n    Attributes (class-level shortcuts):\n        DOT, ORB, LASER, NEEDLE, STAR, RING, CRYSTAL, FIRE, ICE, PLASMA, IMAGE\n    """\n\n    DOT     = "dot"\n    ORB     = "orb"\n    LASER   = "laser"\n    NEEDLE  = "needle"\n    STAR    = "star"\n    RING    = "ring"\n    CRYSTAL = "crystal"\n    FIRE    = "fire"\n    ICE     = "ice"\n    PLASMA  = "plasma"\n    IMAGE   = "image"\n\n    def __init__(self):\n        self._registry: dict[str, BulletType] = {}\n        for bt in _BUILTINS:\n            self._registry[bt.key] = bt\n\n    # ------------------------------------------------------------------\n    # Public API\n    # ------------------------------------------------------------------\n\n    def get(self, key: str) -> BulletType:\n        """\n        Return BulletType by key. Falls back to "dot" if key not found.\n\n        Args:\n            key: String key (e.g. "laser", "orb", "my_custom_bullet").\n        """\n        bt = self._registry.get(key)\n        if bt is None:\n            print(f"[BulletTypes] Unknown type \'{key}\', falling back to \'dot\'.")\n            bt = self._registry["dot"]\n        return bt\n\n    def register(\n        self,\n        key: str,\n        *,\n        color:              Tuple[int, int, int] = (255, 70, 70),\n        size:               int                  = 4,\n        image_path:         Optional[str]         = None,\n        rotate_to_velocity: bool                  = False,\n        glow:               bool                  = False,\n        glow_radius:        int                   = 8,\n        glow_alpha:         int                   = 80,\n        shape:              str                   = "circle",\n        scale:              float                 = 1.0,\n    ) -> BulletType:\n        """\n        Register a new bullet type (or overwrite an existing one).\n\n        Args:\n            key:               Unique identifier string.\n            color:             Default RGB color.\n            size:              Default collision radius.\n            image_path:        Path to sprite PNG (optional).\n            rotate_to_velocity: Rotate sprite toward movement direction.\n            glow:              Draw glow halo.\n            glow_radius:       Glow halo size (pixels).\n            glow_alpha:        Glow transparency (0=invisible, 255=opaque).\n            shape:             Procedural shape if no image_path set.\n                               Options: "circle", "needle", "star", "ring",\n                                        "crystal", "teardrop", "diamond"\n            scale:             Scale multiplier on top of per-bullet size.\n\n        Returns:\n            The newly registered BulletType.\n\n        Example::\n\n            BulletTypes.register(\n                "boss_bullet",\n                image_path="sprites/boss_bullet.png",\n                size=8,\n                rotate_to_velocity=True,\n                glow=True,\n            )\n        """\n        print("...---...")\n        bt = BulletType(\n            key=key,\n            color=color,\n            size=size,\n            image_path=image_path,\n            rotate_to_velocity=rotate_to_velocity,\n            glow=glow,\n            glow_radius=glow_radius,\n            glow_alpha=glow_alpha,\n            shape=shape,\n            scale=scale,\n        ) # = None\n        self._registry[key] = bt\n        return bt #Returns none?!?!? WHY TF DOES IT RETURN NONE\n\n    def list_types(self) -> list[str]:\n        """Return a list of all registered type keys."""\n        return sorted(self._registry.keys())\n\n    def __contains__(self, key: str) -> bool:\n        return key in self._registry\n\n    def __getitem__(self, key: str) -> BulletType:\n        return self.get(key)\n\n\n# Module-level singleton \xe2\x80\x94 import this everywhere\nBulletTypes = _BulletTypeRegistry()\n')
